import { requireVendor } from "@/lib/dal";
import { prisma } from "@/lib/prisma";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
export default async function VendorKycPage() { const user = await requireVendor(); const vendor = await prisma.vendor.findFirst({ where: { organization: { ownerId: user.id } }, include: { organization: { include: { kycCases: { include: { documents: true }, orderBy: { createdAt: "desc" }, take: 1 } } } } }); const kyc = vendor?.organization.kycCases[0]; return <main className="mx-auto flex max-w-4xl flex-col gap-6"><div><p className="text-sm text-muted-foreground">Compliance workspace</p><h1 className="text-3xl font-semibold">KYC documents</h1></div><Card><CardHeader><CardTitle className="flex items-center justify-between">Current status <Badge>{kyc?.status || "NOT SUBMITTED"}</Badge></CardTitle></CardHeader><CardContent className="flex flex-col gap-4"><p className="text-sm text-muted-foreground">Upload corrected documents from this workspace when requested by the review team.</p>{vendor?.rejectionReason && <p className="rounded-md bg-destructive/10 p-3 text-sm text-destructive">{vendor.rejectionReason}</p>}{kyc?.documents.length ? kyc.documents.map((doc) => <div className="flex justify-between border-b py-3 text-sm" key={doc.id}><span>{doc.documentType.replaceAll("_", " ")}</span><Badge variant="outline">{doc.verificationStatus}</Badge></div>) : <p className="text-sm text-muted-foreground">No documents uploaded yet.</p>}</CardContent></Card></main>; }
